  1	// donut-chart — a bundled template (spec §11 G-44): `values` as a
  2	// comma-separated string, slices sweeping clockwise in turn, the first
  3	// slice's share counting up in the centre and a staggered legend.
  4	export const meta = {
  5	  name: "Donut chart",
  6	  durationInFrames: 150,
  7	};
  8	
  9	export const schema = {
 10	  values: { type: "string", default: "45, 30, 15, 10", animate: false },
 11	  labels: { type: "string", default: "Video, Audio, Graphics, Other", animate: false },
 12	  title:  { type: "string", default: "Where the time goes" },
 13	  accent: { type: "color",  default: "#ff5a36" },
 14	};
 15	
 16	const PALETTE = ["#2d7ff9", "#ffd60a", "#34c759", "#af52de", "#ff9f0a", "#5ac8fa"];
 17	
 18	// An arc of the circle (cx, cy, r) from angle a0 to a1, in degrees clockwise
 19	// from twelve o'clock; a full turn is two half arcs.
 20	function arc(cx, cy, r, a0, a1) {
 21	  const at = (a) => {
 22	    const t = ((a - 90) * Math.PI) / 180;
 23	    return `${cx + r * Math.cos(t)} ${cy + r * Math.sin(t)}`;
 24	  };
 25	  if (a1 - a0 >= 359.99) {
 26	    return `M ${at(a0)} A ${r} ${r} 0 1 1 ${at(a0 + 180)} A ${r} ${r} 0 1 1 ${at(a0 + 359.99)}`;
 27	  }
 28	  return `M ${at(a0)} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${at(a1)}`;
 29	}
 30	
 31	export function render(frame, props, ctx) {
 32	  const u = Math.min(ctx.width, ctx.height) / 1080;
 33	  const D = ctx.durationInFrames;
 34	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v))
 35	    .map((v) => Math.max(0, v));
 36	  const labels = props.labels.split(",").map((l) => l.trim());
 37	  const n = values.length;
 38	  const total = values.reduce((a, b) => a + b, 0);
 39	  // A square frame takes the side-by-side layout: a column would not fit its height.
 40	  const landscape = ctx.width >= ctx.height;
 41	  const safeX = ctx.width * 0.05;
 42	  const safeY = ctx.height * 0.05;
 43	  const safeW = ctx.width * 0.9;
 44	  const safeH = ctx.height * 0.9;
 45	  const pad = 60 * u;
 46	  const innerW = safeW - 2 * pad;
 47	  const titleSize = fitText(props.title, innerW, { family: "Montserrat", weight: 900 }, { min: 12 * u, max: 64 * u });
 48	  const rowH = Math.min(78 * u, (landscape ? safeH - 300 * u : 560 * u) / Math.max(1, n));
 49	  const legendH = rowH * n;
 50	  const thick = 64 * u;
 51	  let legendW = Math.min(620 * u, innerW);
 52	  let R;
 53	  let cx;
 54	  let cy;
 55	  let legendX;
 56	  let legendY;
 57	  let blockTop;
 58	  if (landscape) {
 59	    // The donut leaves the legend at least 360u beside it (a square frame's narrow width).
 60	    const gapL = Math.min(140 * u, innerW * 0.1);
 61	    R = Math.min((safeH - 2 * pad - titleSize - 100 * u) / 2 - thick / 2, innerW * 0.22,
 62	      (innerW - thick - gapL - 360 * u) / 2);
 63	    legendW = Math.min(620 * u, innerW - 2 * R - thick - gapL);
 64	    blockTop = safeY + Math.max(pad, (safeH - (titleSize + 70 * u + 2 * R + thick)) / 2);
 65	    const blockW = 2 * R + thick + gapL + legendW;
 66	    cx = Math.max(safeX + pad, (ctx.width - blockW) / 2) + thick / 2 + R;
 67	    cy = blockTop + titleSize + 70 * u + thick / 2 + R;
 68	    legendX = cx + R + thick / 2 + gapL;
 69	    legendY = cy - legendH / 2;
 70	  } else {
 71	    R = innerW * 0.3;
 72	    const blockH = titleSize + 80 * u + 2 * R + thick + 90 * u + legendH;
 73	    blockTop = safeY + Math.max(pad, (safeH - blockH) / 2);
 74	    cx = ctx.width / 2;
 75	    cy = blockTop + titleSize + 80 * u + thick / 2 + R;
 76	    legendX = (ctx.width - legendW) / 2;
 77	    legendY = cy + R + thick / 2 + 90 * u;
 78	  }
 79	  const titleX = landscape ? cx - R - thick / 2 : ctx.width / 2;
 80	  const titleFits = landscape
 81	    ? Math.min(titleSize, fitText(props.title, safeX + safeW - pad - titleX, { family: "Montserrat", weight: 900 },
 82	      { min: 12 * u, max: 64 * u }))
 83	    : titleSize;
 84	  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
 85	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 86	  const sweep = interpolate(frame, [8, 70], [0, 360], { easing: Easing.inOutCubic, clamp: true });
 87	  const gap = n > 1 ? 1.6 : 0;
 88	
 89	  let slices = `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.08"
 90	                        stroke-width="${thick}"/>`;
 91	  let start = 0;
 92	  values.forEach((v, i) => {
 93	    const size = total > 0 ? (v / total) * 360 : 0;
 94	    const shown = Math.min(sweep, start + size) - start;
 95	    if (size > 0 && shown > gap) {
 96	      const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
 97	      slices += `<path d="${arc(cx, cy, R, start + gap / 2, start + shown - gap / 2)}" fill="none"
 98	                       stroke="${colour}" stroke-width="${thick}"/>`;
 99	    }
100	    start += size;
101	  });
102	
103	  const share = total > 0 ? (values[0] / total) * 100 : 0;
104	  const counted = share * interpolate(frame, [8, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
105	  const percentSize = Math.min(120 * u, R * 0.62);
106	  const centreLabel = labels[0] || "";
107	  const centreSize = centreLabel ? fitText(centreLabel, (2 * R - thick) * 0.8, { family: "Montserrat", weight: 800 },
108	    { min: 8 * u, max: 28 * u }) : 28 * u;
109	  const centre = `
110	    <text x="${cx}" y="${cy + percentSize * 0.3}" text-anchor="middle" font-family="IBM Plex Mono"
111	          font-weight="500" font-size="${percentSize}" fill="#ffffff">${Math.round(counted)}%</text>
112	    <text x="${cx}" y="${cy + percentSize * 0.3 + 52 * u}" text-anchor="middle" font-family="Montserrat"
113	          font-weight="800" font-size="${centreSize}" fill="#c8c8d0" opacity="${fade}">${escapeXml(centreLabel)}</text>`;
114	
115	  let legend = "";
116	  // One size for every row's label, the smallest any needs to clear the widest percentage.
117	  const rowSize = Math.min(36 * u, rowH * 0.5);
118	  const sq = rowSize * 0.8;
119	  const pcts = values.map((v) => (total > 0 ? `${Math.round((v / total) * 100)}%` : "0%"));
120	  const pctW = Math.max(0, ...pcts.map((p) => measureText(p, { family: "IBM Plex Mono", size: rowSize, weight: 500 }).width));
121	  const labelRoom = legendW - sq - 22 * u - pctW - 24 * u;
122	  const labelSize = Math.min(rowSize, ...labels.slice(0, n).filter((l) => l).map((l) =>
123	    fitText(l, labelRoom, { family: "Montserrat", weight: 800 }, { min: 8 * u, max: rowSize })));
124	  values.forEach((v, i) => {
125	    const t = spring({ frame: frame - 24 - i * 6, fps: ctx.fps, damping: 16 });
126	    if (t <= 0.001) return;
127	    const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
128	    const y = legendY + rowH * i + rowH / 2;
129	    legend += `<g opacity="${Math.min(1, t)}" transform="translate(${(1 - Math.min(1, t)) * 30 * u} 0)">
130	      <rect x="${legendX}" y="${y - sq / 2}" width="${sq}" height="${sq}" rx="${sq * 0.2}" fill="${colour}"/>
131	      <text x="${legendX + sq + 22 * u}" y="${y + labelSize * 0.36}" font-family="Montserrat" font-weight="800"
132	            font-size="${labelSize}" fill="#ffffff">${escapeXml(labels[i] || "")}</text>
133	      <text x="${legendX + legendW}" y="${y + rowSize * 0.36}" text-anchor="end" font-family="IBM Plex Mono"
134	            font-weight="500" font-size="${rowSize}" fill="#c8c8d0">${pcts[i]}</text></g>`;
135	  });
136	
137	  return svg(ctx, `
138	    <g opacity="${out}">
139	      <text x="${titleX}" y="${blockTop + titleSize * 0.8}" text-anchor="${landscape ? "start" : "middle"}"
140	            font-family="Montserrat" font-weight="900" font-size="${titleFits}" fill="#ffffff"
141	            opacity="${fade}">${escapeXml(props.title)}</text>
142	      ${slices}${centre}${legend}
143	    </g>`, { background: "#15151b" });
144	}
  1	// chapter-card — a bundled template (spec §11 G-44): a full card with a
  2	// large outlined chapter numeral, a kicker whose spacing settles, an accent
  3	// rule drawing across and the title revealed upward.
  4	export const meta = {
  5	  name: "Chapter card",
  6	  durationInFrames: 120,
  7	};
  8	
  9	export const schema = {
 10	  number:     { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
 11	  kicker:     { type: "string", default: "CHAPTER" },
 12	  title:      { type: "string", default: "Getting started" },
 13	  background: { type: "color",  default: "#0b0b10" },
 14	  accent:     { type: "color",  default: "#ff5a36" },
 15	};
 16	
 17	export function render(frame, props, ctx) {
 18	  const u = Math.min(ctx.width, ctx.height) / 1080;
 19	  const D = ctx.durationInFrames;
 20	  const safeX = ctx.width * 0.05;
 21	  const safeW = ctx.width * 0.9;
 22	  const pad = 70 * u;
 23	  const left = safeX + pad;
 24	  const width = safeW - 2 * pad;
 25	  const numeral = String(Math.max(0, Math.min(99, Math.round(props.number)))).padStart(2, "0");
 26	  const numSize = 300 * u;
 27	  const numFont = { family: "Montserrat", size: numSize, weight: 900 };
 28	  const numW = measureText(numeral, numFont).width;
 29	  const titleSize = fitText(props.title, width, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 150 * u });
 30	  const kickerSize = 44 * u;
 31	  const blockH = numSize * 0.74 + 60 * u + titleSize * 0.74 + 40 * u;
 32	  const top = (ctx.height - blockH) / 2;
 33	  const numBase = top + numSize * 0.74;
 34	  const ruleY = numBase + 46 * u;
 35	  const titleBase = ruleY + 34 * u + titleSize * 0.74;
 36	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 37	  const lift = interpolate(frame, [D - 15, D - 1], [0, -24 * u], { easing: Easing.inCubic, clamp: true });
 38	  const numIn = interpolate(frame, [0, 22], [0, 1], { easing: Easing.outCubic, clamp: true });
 39	  const numScale = 1.15 - 0.15 * numIn;
 40	  const kickIn = interpolate(frame, [8, 30], [0, 1], { easing: Easing.outCubic, clamp: true });
 41	  const rule = interpolate(frame, [14, 38], [0, 1], { easing: Easing.inOutCubic, clamp: true });
 42	  const reveal = interpolate(frame, [22, 46], [0, 1], { easing: Easing.outCubic, clamp: true });
 43	  const kickerX = left + numW + 40 * u;
 44	  const kickerMax = left + width - kickerX;
 45	  // The kicker wraps beside the numeral, at most three lines at its widest spacing, shrinking (its
 46	  // spacing in proportion) until it does.
 47	  let kickerFit = kickerSize;
 48	  let kickerLines = [];
 49	  for (;;) {
 50	    const font = { family: "Montserrat", size: kickerFit, weight: 800, letterSpacing: (22 * u * kickerFit) / kickerSize };
 51	    kickerLines = props.kicker.trim() ? wrapText(props.kicker, kickerMax, font) : [];
 52	    if (kickerLines.length <= 3 || kickerFit <= 10 * u) break;
 53	    kickerFit = Math.max(10 * u, kickerFit * 0.9);
 54	  }
 55	  const spacing = ((22 - 14 * kickIn) * u * kickerFit) / kickerSize;
 56	  const kickerLead = kickerFit * 1.2;
 57	  const kickerTop = numBase - numSize * 0.37 + kickerFit * 0.36 - ((kickerLines.length - 1) * kickerLead) / 2;
 58	  const ncx = left + numW / 2;
 59	  const ncy = numBase - numSize * 0.37;
 60	  const ruleW = width * rule;
 61	  const rise = (1 - reveal) * titleSize * 1.15;
 62	  return svg(ctx, `
 63	    <defs>
 64	      <clipPath id="title"><rect x="${safeX}" y="${ruleY + 10 * u}" width="${safeW}" height="${titleBase - ruleY - 10 * u + titleSize * 0.26}"/></clipPath>
 65	    </defs>
 66	    <g transform="translate(0 ${lift})">
 67	      <g transform="translate(${ncx} ${ncy}) scale(${numScale}) translate(${-ncx} ${-ncy})">
 68	        <text x="${left}" y="${numBase}" font-family="Montserrat" font-weight="900" font-size="${numSize}" fill="none"
 69	              stroke="${props.accent}" stroke-width="${4 * u}" stroke-opacity="${numIn * out}">${numeral}</text>
 70	      </g>
 71	      <text x="${kickerX}" y="${kickerTop}" font-family="Montserrat" font-weight="800"
 72	            font-size="${kickerFit}" letter-spacing="${spacing}" fill="#d8d8e0"
 73	            fill-opacity="${kickIn * out}">${kickerLines.map((line, i) =>
 74	              `<tspan x="${kickerX}" y="${kickerTop + i * kickerLead}">${escapeXml(line)}</tspan>`).join("")}</text>
 75	      ${ruleW > 0.5 ? `<rect x="${left}" y="${ruleY}" width="${ruleW}" height="${6 * u}" fill="${props.accent}"
 76	            fill-opacity="${out}"/>` : ""}
 77	      <g clip-path="url(#title)">
 78	        <text x="${left}" y="${titleBase + rise}" font-family="Montserrat" font-weight="900" font-size="${titleSize}"
 79	              fill="#ffffff" fill-opacity="${out}">${escapeXml(props.title)}</text>
 80	      </g>
 81	    </g>`, { background: props.background });
 82	}

