  6	  durationInFrames: 120,
  7	};
  8	
  9	export const schema = {
 10	  number:     { type: "number", default: 1, min: 0, max: 99, step: 1, animate: false },
 11	  kicker:     { type: "string", default: "CHAPTER" },
 12	  title:      { type: "string", default: "Getting started" },
 13	  background: { type: "color",  default: "#0b0b10" },
 14	  accent:     { type: "color",  default: "#ff5a36" },
 15	};
 16	
 17	export function render(frame, props, ctx) {
 18	  const u = Math.min(ctx.width, ctx.height) / 1080;
 19	  const D = ctx.durationInFrames;
 20	  const safeX = ctx.width * 0.05;
 21	  const safeW = ctx.width * 0.9;
 22	  const pad = 70 * u;
 23	  const left = safeX + pad;
 24	  const width = safeW - 2 * pad;
 25	  const numeral = String(Math.max(0, Math.min(99, Math.round(props.number)))).padStart(2, "0");
 26	  const numSize = 300 * u;
 27	  const numFont = { family: "Montserrat", size: numSize, weight: 900 };
 28	  const numW = measureText(numeral, numFont).width;
 29	  const titleSize = fitText(props.title, width, { family: "Montserrat", weight: 900 }, { min: 16 * u, max: 150 * u });
 30	  const kickerSize = 44 * u;
 31	  const blockH = numSize * 0.74 + 60 * u + titleSize * 0.74 + 40 * u;
 32	  const top = (ctx.height - blockH) / 2;
 33	  const numBase = top + numSize * 0.74;
 34	  const ruleY = numBase + 46 * u;
 35	  const titleBase = ruleY + 34 * u + titleSize * 0.74;
 36	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 37	  const lift = interpolate(frame, [D - 15, D - 1], [0, -24 * u], { easing: Easing.inCubic, clamp: true });
 38	  const numIn = interpolate(frame, [0, 22], [0, 1], { easing: Easing.outCubic, clamp: true });
 39	  const numScale = 1.15 - 0.15 * numIn;
 40	  const kickIn = interpolate(frame, [8, 30], [0, 1], { easing: Easing.outCubic, clamp: true });
 41	  const rule = interpolate(frame, [14, 38], [0, 1], { easing: Easing.inOutCubic, clamp: true });
 42	  const reveal = interpolate(frame, [22, 46], [0, 1], { easing: Easing.outCubic, clamp: true });
 43	  const kickerX = left + numW + 40 * u;
 44	  const kickerMax = left + width - kickerX;
 45	  // The kicker wraps beside the numeral, at most three lines at its widest spacing, shrinking (its
 46	  // spacing in proportion) until it does.
 47	  let kickerFit = kickerSize;
 48	  let kickerLines = [];
 49	  for (;;) {
 50	    const font = { family: "Montserrat", size: kickerFit, weight: 800, letterSpacing: (22 * u * kickerFit) / kickerSize };
 51	    kickerLines = props.kicker.trim() ? wrapText(props.kicker, kickerMax, font) : [];
 52	    if (kickerLines.length <= 3 || kickerFit <= 10 * u) break;
 53	    kickerFit = Math.max(10 * u, kickerFit * 0.9);
 54	  }
 55	  const spacing = ((22 - 14 * kickIn) * u * kickerFit) / kickerSize;
 56	  const kickerLead = kickerFit * 1.2;
 57	  const kickerTop = numBase - numSize * 0.37 + kickerFit * 0.36 - ((kickerLines.length - 1) * kickerLead) / 2;
 58	  const ncx = left + numW / 2;
 59	  const ncy = numBase - numSize * 0.37;
 60	  const ruleW = width * rule;
 61	  const rise = (1 - reveal) * titleSize * 1.15;
 62	  return svg(ctx, `
 63	    <defs>
 64	      <clipPath id="title"><rect x="${safeX}" y="${ruleY + 10 * u}" width="${safeW}" height="${titleBase - ruleY - 10 * u + titleSize * 0.26}"/></clipPath>
 65	    </defs>
 66	    <g transform="translate(0 ${lift})">
 67	      <g transform="translate(${ncx} ${ncy}) scale(${numScale}) translate(${-ncx} ${-ncy})">
 68	        <text x="${left}" y="${numBase}" font-family="Montserrat" font-weight="900" font-size="${numSize}" fill="none"
 69	              stroke="${props.accent}" stroke-width="${4 * u}" stroke-opacity="${numIn * out}">${numeral}</text>
 70	      </g>
 71	      <text x="${kickerX}" y="${kickerTop}" font-family="Montserrat" font-weight="800"
 72	            font-size="${kickerFit}" letter-spacing="${spacing}" fill="#d8d8e0"
 73	            fill-opacity="${kickIn * out}">${kickerLines.map((line, i) =>
 74	              `<tspan x="${kickerX}" y="${kickerTop + i * kickerLead}">${escapeXml(line)}</tspan>`).join("")}</text>
 75	      ${ruleW > 0.5 ? `<rect x="${left}" y="${ruleY}" width="${ruleW}" height="${6 * u}" fill="${props.accent}"
 76	            fill-opacity="${out}"/>` : ""}
 77	      <g clip-path="url(#title)">
 78	        <text x="${left}" y="${titleBase + rise}" font-family="Montserrat" font-weight="900" font-size="${titleSize}"
 79	              fill="#ffffff" fill-opacity="${out}">${escapeXml(props.title)}</text>
 80	      </g>
 81	    </g>`, { background: props.background });
 82	}

