  1	//! The bundled templates (spec §11 G-44): every module of `tests/graphics/`
  2	//! except road map 10's six fixtures draws without a warning, with no `NaN`
  3	//! or `Infinity` in its SVG, and nothing outside the 90 % title-safe
  4	//! rectangle moves — at 1920×1080, 1080×1920 and 1080×1080, every fifth
  5	//! frame and the last, which every outro leaves bare. Every combination of
  6	//! a template's `enum` options is held to the same through its entrance,
  7	//! its hold and its last frame, and so is every template with its `string`
  8	//! properties long (`templates/long_text.rs`). `project.yml` copies exactly
  9	//! the folder's modules.
 10	//! `GRAPHIC_TEMPLATE_PNGS=<dir>` writes frames 12, D/2 and D−8 of each, over
 11	//! opaque `#6e6e74`, for a person to look at.
 12	
 13	mod common;
 14	
 15	use std::fs;
 16	use std::time::Instant;
 17	
 18	use graphic::{rasterize, Module};
 19	use serde_json::Value;
 20	
 21	use common::{shared, BUDGET_MS, FIXTURES, GRAPHICS};
 22	
 23	#[path = "templates/long_text.rs"]
 24	mod long_text;
 25	
 26	const SIZES: [(u32, u32); 3] = [(1920, 1080), (1080, 1920), (1080, 1080)];
 27	const FPS: f64 = 30.0;
 28	
 29	/// The template stems: the folder's `*.js` less the fixtures, sorted.
 30	fn templates() -> Vec<String> {
 31	    let mut stems: Vec<String> = fs::read_dir(GRAPHICS)
 32	        .expect("tests/graphics")
 33	        .map(|entry| entry.expect("a directory entry").path())
 34	        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
 35	        .map(|path| path.file_stem().unwrap().to_string_lossy().into_owned())
 36	        .filter(|stem| !FIXTURES.contains(&stem.as_str()))
 37	        .collect();
 38	    stems.sort();
 39	    assert!(!stems.is_empty(), "no template in {GRAPHICS}");
 40	    stems
 41	}
 42	
 43	fn duration(module: &Module) -> i64 {
 44	    module.meta()["durationInFrames"]
 45	        .as_i64()
 46	        .expect("a template's meta.durationInFrames")
 47	}
 48	
 49	/// One frame drawn: the BGRA, or every problem with it named.
 50	fn draw(
 51	    module: &Module,
 52	    frame: i64,
 53	    props: &Value,
 54	    (width, height): (u32, u32),
 55	) -> Result<Vec<u8>, String> {
 56	    let name = module.name();
 57	    let ctx = common::ctx(frame, FPS, duration(module), width, height);
 58	    let at = format!("{name} {width}x{height} frame {frame}");
 59	    let (svg, warnings) = graphic::svg(module, frame, props, &ctx, BUDGET_MS)
 60	        .map_err(|d| format!("{at}: {}", d.message))?;
 61	    if !warnings.is_empty() {
 62	        return Err(format!(
 63	            "{at}: svg warned {:?}",
 64	            common::messages(&warnings)
 65	        ));
 66	    }
 67	    for bad in ["NaN", "Infinity"] {
 68	        if svg.contains(bad) {
 69	            return Err(format!("{at}: the SVG holds {bad}"));
 70	        }
 71	    }
 72	    let stride = width as usize * 4;
 73	    let mut out = vec![0u8; stride * height as usize];
 74	    let raster = rasterize(&shared(), &svg, width, height, &mut out, stride)
 75	        .map_err(|d| format!("{at}: rasterize refused: {}", d.message))?;
 76	    if !raster.is_empty() {
 77	        return Err(format!(
 78	            "{at}: rasterize warned {:?}",
 79	            common::messages(&raster)
 80	        ));
 81	    }
 82	    Ok(out)
 83	}
 84	
 85	/// Whether pixel `(x, y)` is outside title-safe: x ∈ [0.05W, 0.95W),
 86	/// y ∈ [0.05H, 0.95H).
 87	fn outside(x: u32, y: u32, (width, height): (u32, u32)) -> bool {
 88	    x < width * 5 / 100 || x >= width * 95 / 100 || y < height * 5 / 100 || y >= height * 95 / 100
 89	}
 90	
 91	/// The first pixel outside title-safe where `a` and `b` differ.
 92	fn first_difference(a: &[u8], b: &[u8], size: (u32, u32)) -> Option<(u32, u32)> {
 93	    let (width, height) = size;
 94	    for y in 0..height {
 95	        for x in 0..width {
 96	            let at = (y as usize * width as usize + x as usize) * 4;
 97	            if outside(x, y, size) && a[at..at + 4] != b[at..at + 4] {
 98	                return Some((x, y));
 99	            }
100	        }
101	    }
102	    None
103	}
104	
105	/// Frame 0's alpha outside title-safe, when it is one value (0 or 255).
106	fn border_alpha(frame0: &[u8], size: (u32, u32)) -> Result<u8, String> {
107	    let (width, height) = size;
108	    let mut seen: Option<u8> = None;
109	    for y in 0..height {
110	        for x in 0..width {
111	            if !outside(x, y, size) {
112	                continue;
113	            }
114	            let alpha = frame0[(y as usize * width as usize + x as usize) * 4 + 3];
115	            match seen {
116	                None => seen = Some(alpha),
117	                Some(a) if a != alpha => {
118	                    return Err(format!(
119	                        "alpha {a} and {alpha} (at {x},{y}) outside title-safe"
120	                    ))
121	                }
122	                _ => {}
123	            }
124	        }
125	    }
126	    match seen {
127	        Some(a @ (0 | 255)) => Ok(a),
128	        other => Err(format!("alpha {other:?} outside title-safe, not 0 or 255")),
129	    }
130	}
131	
132	/// Writes `frame` of `module` at `size` over opaque `#6e6e74` as an RGB PNG.
133	fn dump(dir: &str, module: &Module, frame: i64, size: (u32, u32)) {
134	    let (width, height) = size;
135	    let bgra = draw(module, frame, &module.defaults(), size).unwrap_or_else(|e| panic!("{e}"));
136	    let grey = [0x6e_u32, 0x6e, 0x74];
137	    let rgb: Vec<u8> = bgra
138	        .chunks_exact(4)
139	        .flat_map(|p| {
140	            let under = 255 - p[3] as u32;
141	            let over = |src: u8, bg: u32| (src as u32 + (bg * under + 127) / 255).min(255) as u8;
142	            [
143	                over(p[2], grey[0]),
144	                over(p[1], grey[1]),
145	                over(p[0], grey[2]),
146	            ]
147	        })
148	        .collect();
149	    fs::create_dir_all(dir).expect("the PNG folder");
150	    let path = format!("{dir}/{}-{width}x{height}-{frame}.png", module.name());
151	    let file = fs::File::create(&path).expect("a PNG file");
152	    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), width, height);
153	    encoder.set_color(png::ColorType::Rgb);
154	    encoder.set_depth(png::BitDepth::Eight);
155	    let mut writer = encoder.write_header().expect("a PNG header");
156	    writer.write_image_data(&rgb).expect("PNG data");
157	}
158	
159	/// The frames sampled: 0, 5, 10, … and the last.
160	fn sampled(duration: i64) -> Vec<i64> {
161	    let mut frames: Vec<i64> = (0..duration).step_by(5).collect();
162	    if frames.last() != Some(&(duration - 1)) {
163	        frames.push(duration - 1);
164	    }
165	    frames
166	}
167	
168	/// The first pixel of the last frame that is not bare: for an overlay
169	/// (`border` 0) one with any alpha, for a card one that differs from the
170	/// background, frame 0's pixel (0, 0).
171	fn not_bare(last: &[u8], frame0: &[u8], border: u8, width: u32) -> Option<(u32, u32)> {
172	    let at = |i: usize| ((i % width as usize) as u32, (i / width as usize) as u32);
173	    last.chunks_exact(4)
174	        .position(|p| {
175	            if border == 0 {
176	                p[3] != 0
177	            } else {
178	                p != &frame0[..4]
179	            }
180	        })
181	        .map(at)
182	}
183	
184	/// Draws `frames` (frame 0 first) of `module` with `props` at `size` and
185	/// holds them to G-44 (b) and (c): frame 0 has one alpha outside title-safe
186	/// (0 or 255), no later frame differs from it there, and the last frame,
187	/// `D − 1`, when sampled, is bare (`not_bare`) — every outro fades all of
188	/// its content. A frame 0 that fails to draw skips the comparisons. Answers
189	/// each frame's svg+rasterize ms.
190	fn check(
191	    module: &Module,
192	    props: &Value,
193	    frames: &[i64],
194	    size: (u32, u32),
195	    what: &str,
196	    failures: &mut Vec<String>,
197	) -> Vec<f64> {
198	    let last = duration(module) - 1;
199	    let mut times = Vec::new();
200	    let mut base: Option<(Vec<u8>, u8)> = None;
201	    for &frame in frames {
202	        let started = Instant::now();
203	        let drawn = draw(module, frame, props, size);
204	        times.push(started.elapsed().as_secs_f64() * 1000.0);
205	        let bgra = match drawn {
206	            Ok(bgra) => bgra,
207	            Err(e) => {
208	                failures.push(format!("{what}: {e}"));
209	                continue;
210	            }
211	        };
212	        if frame == 0 {
213	            match border_alpha(&bgra, size) {
214	                Ok(alpha) => base = Some((bgra, alpha)),
215	                Err(e) => failures.push(format!("{what} {size:?} frame 0: {e}")),
216	            }
217	            continue;
218	        }
219	        let Some((first, alpha)) = &base else {
220	            continue;
221	        };
222	        if let Some((x, y)) = first_difference(first, &bgra, size) {
223	            failures.push(format!(
224	                "{what} {size:?} frame {frame}: pixel ({x}, {y}) outside title-safe differs from frame 0"
225	            ));
226	        }
227	        if frame == last {
228	            if let Some((x, y)) = not_bare(&bgra, first, *alpha, size.0) {
229	                failures.push(format!(
230	                    "{what} {size:?} last frame {frame}: pixel ({x}, {y}) is still drawn after the outro"
231	                ));
232	            }
233	        }
234	    }
235	    times
236	}
237	
238	#[test]
239	fn every_template_draws_cleanly_inside_title_safe() {
240	    let dump_dir = std::env::var("GRAPHIC_TEMPLATE_PNGS").ok();
241	    let mut failures = Vec::new();
242	    for stem in templates() {
243	        let module = common::module(&stem);
244	        let props = module.defaults();
245	        let d = duration(&module);
246	        for size in SIZES {
247	            let mut times = check(&module, &props, &sampled(d), size, &stem, &mut failures);
248	            if size == SIZES[0] {
249	                times.sort_by(|a, b| a.partial_cmp(b).unwrap());
250	                let p95 = times[((times.len() as f64 * 0.95).ceil() as usize).max(1) - 1];
251	                println!("{stem}: p95 svg+rasterize {p95:.2} ms at 1920x1080");
252	            }
253	            if let Some(dir) = &dump_dir {
254	                for frame in [12, d / 2, d - 8] {
255	                    dump(dir, &module, frame, size);
256	                }
257	            }
258	        }
259	    }
260	    assert!(failures.is_empty(), "{}", failures.join("\n"));
261	}
262	
263	/// Props at the schema's edges that the enum pass also draws: a window
264	/// frame filling title-safe, and one leaving its shadow a thin margin.
265	fn edges() -> Vec<(&'static str, Value)> {
266	    vec![
267	        ("window-frame", serde_json::json!({"scale": 1})),
268	        ("window-frame", serde_json::json!({"scale": 0.97})),
269	    ]
270	}
271	
272	/// Every combination of a template's `enum` options over `base`, each as
273	/// `(what, props)`; `what` names the options chosen, and is empty for
274	/// `base` itself when the template has no `enum`.
275	fn combinations(module: &Module, base: Value) -> Vec<(String, Value)> {
276	    let mut out = vec![(String::new(), base)];
277	    for (key, entry) in module.schema().as_object().expect("a schema object") {
278	        if entry["type"] != "enum" {
279	            continue;
280	        }
281	        let options = entry["options"].as_array().expect("an enum's options");
282	        out = out
283	            .iter()
284	            .flat_map(|(what, props)| {
285	                options.iter().map(move |option| {
286	                    let mut props = props.clone();
287	                    props[key] = option.clone();
288	                    (
289	                        format!("{what} {key}={}", option.as_str().unwrap_or("?")),
290	                        props,
291	                    )
292	                })
293	            })
294	            .collect();
295	    }
296	    out
297	}
298	
299	/// Every combination of a template's `enum` options, the other props at
300	/// their defaults, plus `edges()`: each as `(what, props)`.
301	fn variants(stem: &str, module: &Module) -> Vec<(String, Value)> {
302	    let mut out = combinations(module, module.defaults());
303	    for (_, overrides) in edges().into_iter().filter(|(s, _)| *s == stem) {
304	        let mut props = module.defaults();
305	        for (key, value) in overrides.as_object().unwrap() {
306	            props[key] = value.clone();
307	        }
308	        out.push((format!(" {overrides}"), props));
309	    }
310	    out.into_iter()
311	        .filter(|(what, _)| !what.is_empty())
312	        .map(|(what, props)| (format!("{stem}{what}"), props))
313	        .collect()
314	}
315	
316	#[test]
317	fn every_enum_option_draws_cleanly_inside_title_safe() {
318	    let mut failures = Vec::new();
319	    let mut drawn = 0;
320	    for stem in templates() {
321	        let module = common::module(&stem);
322	        let d = duration(&module);
323	        for (what, props) in variants(&stem, &module) {
324	            drawn += 1;
325	            for size in SIZES {
326	                let frames = [0, 3, 6, 9, 12, d / 2, d - 1];
327	                check(&module, &props, &frames, size, &what, &mut failures);
328	            }
329	        }
330	    }
331	    assert!(drawn > 0, "no template has an enum");
332	    assert!(failures.is_empty(), "{}", failures.join("\n"));
333	}
334	
335	#[test]
336	fn degenerate_props_draw_cleanly() {
337	    let cases = [
338	        ("line-chart", serde_json::json!({"values": "5"})),
339	        ("donut-chart", serde_json::json!({"values": "0, 0"})),
340	        ("gauge", serde_json::json!({"min": 0, "max": 0, "value": 0})),
341	    ];
342	    let mut failures = Vec::new();
343	    for (stem, overrides) in cases {
344	        let module = common::module(stem);
345	        let mut props = module.defaults();
346	        for (key, value) in overrides.as_object().unwrap() {
347	            props[key] = value.clone();
348	        }
349	        let d = duration(&module);
350	        for size in SIZES {
351	            for frame in [0, d / 2, d - 1] {
352	                if let Err(e) = draw(&module, frame, &props, size) {
353	                    failures.push(e);
354	                }
355	            }
356	        }
357	    }
358	    assert!(failures.is_empty(), "{}", failures.join("\n"));
359	}
360	
361	/// The file names listed under `key:` in the "Copy Graphic Templates" phase.
362	fn listed(phase: &str, key: &str) -> Vec<String> {
363	    let mut names: Vec<String> = phase
364	        .lines()
365	        .skip_while(|line| line.trim() != format!("{key}:"))
366	        .skip(1)
367	        .take_while(|line| line.trim_start().starts_with("- "))
368	        .map(|line| line.rsplit('/').next().unwrap().trim().to_string())
369	        .collect();
370	    names.sort();
371	    names
372	}
373	
374	#[test]
375	fn project_yml_lists_every_template() {
376	    let yml = fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../project.yml"))
377	        .expect("project.yml");
378	    let start = yml
379	        .find("- name: Copy Graphic Templates")
380	        .expect("the Copy Graphic Templates phase");
381	    let rest = &yml[start + 1..];
382	    let phase = &rest[..rest.find("- name:").unwrap_or(rest.len())];
383	    let mut files: Vec<String> = fs::read_dir(GRAPHICS)
384	        .expect("tests/graphics")
385	        .map(|entry| entry.expect("a directory entry").path())
386	        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
387	        .map(|path| path.file_name().unwrap().to_string_lossy().into_owned())
388	        .collect();
389	    files.sort();
390	    assert_eq!(listed(phase, "inputFiles"), files, "inputFiles");
391	    assert_eq!(listed(phase, "outputFiles"), files, "outputFiles");
392	}

