 35	        .map(|path| path.file_stem().unwrap().to_string_lossy().into_owned())
 36	        .filter(|stem| !FIXTURES.contains(&stem.as_str()))
 37	        .collect();
 38	    stems.sort();
 39	    assert!(!stems.is_empty(), "no template in {GRAPHICS}");
 40	    stems
