 49	/// One frame drawn: the BGRA, or every problem with it named.
 50	fn draw(
 51	    module: &Module,
 52	    frame: i64,
 53	    props: &Value,
 54	    (width, height): (u32, u32),
 55	) -> Result<Vec<u8>, String> {
 56	    let name = module.name();
 57	    let ctx = common::ctx(frame, FPS, duration(module), width, height);
 58	    let at = format!("{name} {width}x{height} frame {frame}");
 59	    let (svg, warnings) = graphic::svg(module, frame, props, &ctx, BUDGET_MS)
 60	        .map_err(|d| format!("{at}: {}", d.message))?;
 61	    if !warnings.is_empty() {
 62	        return Err(format!(
 63	            "{at}: svg warned {:?}",
 64	            common::messages(&warnings)
 65	        ));
 66	    }
 67	    for bad in ["NaN", "Infinity"] {
 68	        if svg.contains(bad) {
 69	            return Err(format!("{at}: the SVG holds {bad}"));
 70	        }
 71	    }
 72	    let stride = width as usize * 4;
 73	    let mut out = vec![0u8; stride * height as usize];
 74	    let raster = rasterize(&shared(), &svg, width, height, &mut out, stride)
 75	        .map_err(|d| format!("{at}: rasterize refused: {}", d.message))?;
 76	    if !raster.is_empty() {
 77	        return Err(format!(
 78	            "{at}: rasterize warned {:?}",
 79	            common::messages(&raster)
 80	        ));
 81	    }
 82	    Ok(out)
 83	}
