 85	/// Whether pixel `(x, y)` is outside title-safe: x ∈ [0.05W, 0.95W),
 86	/// y ∈ [0.05H, 0.95H).
 87	fn outside(x: u32, y: u32, (width, height): (u32, u32)) -> bool {
 88	    x < width * 5 / 100 || x >= width * 95 / 100 || y < height * 5 / 100 || y >= height * 95 / 100
 89	}
 90	
 91	/// The first pixel outside title-safe where `a` and `b` differ.
 92	fn first_difference(a: &[u8], b: &[u8], size: (u32, u32)) -> Option<(u32, u32)> {
 93	    let (width, height) = size;
 94	    for y in 0..height {
 95	        for x in 0..width {
 96	            let at = (y as usize * width as usize + x as usize) * 4;
 97	            if outside(x, y, size) && a[at..at + 4] != b[at..at + 4] {
 98	                return Some((x, y));
 99	            }
100	        }
101	    }
102	    None
103	}
104	
105	/// Frame 0's alpha outside title-safe, when it is one value (0 or 255).
106	fn border_alpha(frame0: &[u8], size: (u32, u32)) -> Result<u8, String> {
107	    let (width, height) = size;
108	    let mut seen: Option<u8> = None;
109	    for y in 0..height {
110	        for x in 0..width {
111	            if !outside(x, y, size) {
112	                continue;
113	            }
114	            let alpha = frame0[(y as usize * width as usize + x as usize) * 4 + 3];
115	            match seen {
116	                None => seen = Some(alpha),
117	                Some(a) if a != alpha => {
118	                    return Err(format!(
119	                        "alpha {a} and {alpha} (at {x},{y}) outside title-safe"
120	                    ))
121	                }
122	                _ => {}
123	            }
124	        }
125	    }
126	    match seen {
127	        Some(a @ (0 | 255)) => Ok(a),
128	        other => Err(format!("alpha {other:?} outside title-safe, not 0 or 255")),
129	    }
130	}
