159	/// The frames sampled: 0, 5, 10, … and the last.
160	fn sampled(duration: i64) -> Vec<i64> {
161	    let mut frames: Vec<i64> = (0..duration).step_by(5).collect();
162	    if frames.last() != Some(&(duration - 1)) {
163	        frames.push(duration - 1);
164	    }
165	    frames
166	}
