299	/// Every combination of a template's `enum` options, the other props at
300	/// their defaults, plus `edges()`: each as `(what, props)`.
301	fn variants(stem: &str, module: &Module) -> Vec<(String, Value)> {
302	    let mut out = combinations(module, module.defaults());
303	    for (_, overrides) in edges().into_iter().filter(|(s, _)| *s == stem) {
304	        let mut props = module.defaults();
305	        for (key, value) in overrides.as_object().unwrap() {
306	            props[key] = value.clone();
307	        }
308	        out.push((format!(" {overrides}"), props));
309	    }
310	    out.into_iter()
311	        .filter(|(what, _)| !what.is_empty())
312	        .map(|(what, props)| (format!("{stem}{what}"), props))
313	        .collect()
314	}
